update public.app_settings
   set value = $ph$[{"ko": "세 살 버릇 여든까지 간다", "rom": "Se sal beoreut yeodeun-kkaji ganda", "en": "Habits formed early last a lifetime.", "intro_ko": "어릴 때 들인 습관은 평생 간다는 뜻이에요.", "intro": "Childhood habits persist throughout one's entire life.", "nuance": "Used when cautioning about early upbringing or explaining why someone has a lifelong trait.", "level": "Tree", "examples": [{"ko": "아이에게 좋은 습관을 가르쳐야 해요. 세 살 버릇 여든까지 간다니까요.", "en": "We must teach children good habits. After all, childhood habits last until old age."}, {"ko": "그는 어려서부터 책을 많이 읽었어. 세 살 버릇 여든까지 간다더니 지금도 책벌레네.", "en": "He read a lot as a child. They say childhood habits last forever—he's still a bookworm now."}], "related": ["어린 나뭇가지는 굽히기 쉽다", "버릇이 제2의 천성이다"], "related_v": 0}, {"ko": "가는 말이 고와야 오는 말이 곱다", "rom": "Ganeun mari gowaya oneun mari gopda", "en": "If you speak kindly, others will too.", "intro_ko": "", "intro": "", "nuance": "", "level": "", "examples": [], "related": [], "related_v": 0}, {"ko": "백문이 불여일견", "rom": "Baekmuni buryeo ilgyeon", "en": "Seeing once is better than hearing a hundred times.", "intro_ko": "백 번 듣는 것보다 한 번 보는 게 낫다.", "intro": "Direct experience beats secondhand information every time.", "nuance": "Used when explaining why observation or hands-on practice matters more than explanation alone.", "level": "Tree", "examples": [{"ko": "백문이 불여일견이니 직접 가서 확인해보세요.", "en": "Seeing is better than hearing—go check it out yourself."}, {"ko": "아무리 설명해도 백문이 불여일견이에요.", "en": "No matter how much I explain, seeing once is worth more."}], "related": ["눈으로 봐야 안다", "백견이 불여일행"], "related_v": 0}, {"ko": "고생 끝에 낙이 온다", "rom": "gosaeng kkeute nagi on-da", "en": "After hardship comes happiness; every cloud has a silver lining", "intro_ko": "", "intro": "A proverb meaning that joy and good fortune eventually come after a period of suffering or hard work. It expresses hope that difficult times will pass.", "nuance": "This is an encouraging, optimistic saying often used to comfort someone going through a tough time. It suggests that hardship is temporary and better days are coming.", "level": "", "examples": [{"ko": "시험 공부가 힘들지만 고생 끝에 낙이 온다고 생각하며 열심히 하고 있어요.", "en": "The exam studying is tough, but I'm working hard thinking that joy comes after hardship."}, {"ko": "회사에서 힘든 프로젝트를 끝냈어요. 정말 고생 끝에 낙이 온다는 말이 맞네요!", "en": "I finished the tough project at work. That saying about joy coming after hardship is really true!"}, {"ko": "지금은 어렵지만 고생 끝에 낙이 온다니까 조금만 더 참아요.", "en": "It's hard now, but since good things come after hardship, let's hold on a bit longer."}], "related": ["힘내", "견디다", "행운이 찾아오다"], "related_v": 0}, {"ko": "등잔 밑이 어둡다", "rom": "Deungjan michi eodupda", "en": "The darkest place is under the lamp", "intro_ko": "가까운 곳을 못 본다는 뜻이에요.", "intro": "You miss what's closest to you.", "nuance": "Used when someone overlooks an obvious solution or truth right in front of them.", "level": "Tree", "examples": [{"ko": "등잔 밑이 어두워서 자기 실수를 못 봤어요.", "en": "He missed his own mistake because he couldn't see what was right in front of him."}, {"ko": "등잔 밑이 어둡다고, 가장 가까운 사람의 마음을 몰랐다.", "en": "Like the lamp's darkness, he didn't notice the feelings of the person closest to him."}], "related": ["코 앞이 깜깜하다", "눈에 띄지 않다", "가까운 것이 먼 것"], "related_v": 0}, {"ko": "티끌 모아 태산", "rom": "Tikkeul moa taesa", "en": "Many small things make something big", "intro_ko": "", "intro": "This proverb uses the image of dust particles accumulating into a mountain to express how small, repeated efforts compound into something large and significant. It reflects the Korean cultural value of persistence and incremental progress, commonly taught to children as encouragement that even tiny contributions matter over time.", "nuance": "Koreans use this phrase in motivational or advisory contexts—when encouraging someone not to give up on a goal, or when explaining why consistent small actions lead to big results. It's neither formal nor casual, fitting equally in a parent's advice, a teacher's lesson, or workplace discussion about long-term planning. It doesn't apply to sudden, large achievements or one-time efforts.", "level": "", "examples": [{"ko": "티끌 모아 태산이니까 매일 조금씩 저축해.", "en": "Since many small things make something big, save a little bit every day."}, {"ko": "티끌 모아 태산이라는 말처럼 꾸준히 노력하면 성공할 거야.", "en": "Just like the saying 'many small things make something big,' if you keep trying steadily, you'll succeed."}, {"ko": "30분씩 매일 공부하는 것도 티끌 모아 태산이 되겠지.", "en": "Studying 30 minutes every day will also add up to something big, like dust becoming a mountain."}], "related": ["빈틈없이", "꾸준함이 최고", "작은 것이 모여 큰 것이 된다"], "related_v": 0}, {"ko": "하늘의 별 따기", "rom": "Haneurui byeol ttagi", "en": "As hard as picking a star from the sky.", "intro_ko": "거의 불가능한 일을 뜻해요.", "intro": "An almost impossible task or goal.", "nuance": "Used when something requires extreme difficulty or seems practically unachievable.", "level": "Tree", "examples": [{"ko": "그 목표는 하늘의 별 따기나 다름없어.", "en": "That goal is nearly as impossible as picking a star from the sky."}, {"ko": "좋은 일자리를 구하는 게 하늘의 별 따기예요.", "en": "Finding a good job is like trying to pick a star from the sky."}], "related": ["낙타가 바늘구멍 들어가기", "공중에 성 쌓기"], "related_v": 3}, {"ko": "시작이 반이다", "rom": "Sijagi banida", "en": "Starting is half the battle.", "intro_ko": "일을 시작하는 것 자체가 이미 반은 한 것과 같다는 뜻이에요.", "intro": "Getting started is already half of finishing.", "nuance": "Said to encourage someone who keeps putting off a task.", "level": "Sprout", "examples": [{"ko": "운동을 시작하기가 제일 어려워요. 그래도 시작이 반이에요.", "en": "Starting to exercise is the hardest part. But starting is half the battle."}, {"ko": "일단 첫 문장만 써 봐. 시작이 반이잖아.", "en": "Just write the first sentence. Starting is half the battle, right?"}], "related": ["천 리 길도 한 걸음부터"], "related_v": 2}, {"ko": "천 리 길도 한 걸음부터", "rom": "Cheon ri gildo han georeumbuteo", "en": "A journey of a thousand miles begins with a single step.", "intro_ko": "아무리 큰일도 작은 것부터 시작해야 한다는 뜻이에요.", "intro": "Even the biggest goal starts with one small step.", "nuance": "Used when someone feels overwhelmed by a long-term goal.", "level": "Tree", "examples": [{"ko": "한국어가 어렵게 느껴져도 천 리 길도 한 걸음부터예요.", "en": "Even if Korean feels hard, a long journey starts with one step."}, {"ko": "오늘은 단어 열 개만 외워요. 천 리 길도 한 걸음부터니까요.", "en": "Let's just memorize ten words today. Every long journey starts with a single step."}], "related": ["시작이 반이다", "티끌 모아 태산"], "related_v": 2}, {"ko": "가는 날이 장날", "rom": "Ganeun nari jangnal", "en": "The day you go happens to be market day.", "intro_ko": "어떤 일을 하려고 갔는데 마침 예상하지 못한 일이 생겼을 때 쓰는 말이에요.", "intro": "Said when something unexpected (usually inconvenient) happens just when you show up.", "nuance": "Most often used with a sigh: the shop was closed, it rained, the line was huge.", "level": "Tree", "examples": [{"ko": "맛집에 갔는데 휴무일이었어요. 가는 날이 장날이네요.", "en": "I went to the famous restaurant, but it was closed that day. Just my luck."}, {"ko": "오랜만에 공원에 갔더니 비가 왔어. 가는 날이 장날이야.", "en": "I finally went to the park and it rained. Of all days."}], "related": [], "related_v": 2}, {"ko": "누워서 떡 먹기", "rom": "Nuwoseo tteok meokgi", "en": "Eating rice cake lying down — a piece of cake.", "intro_ko": "아주 쉬운 일이라는 뜻이에요.", "intro": "Something extremely easy.", "nuance": "Casual; like \"a piece of cake\" in English.", "level": "Sprout", "examples": [{"ko": "이 문제는 누워서 떡 먹기예요.", "en": "This problem is a piece of cake."}, {"ko": "라면 끓이는 건 누워서 떡 먹기지.", "en": "Making ramen is a piece of cake."}], "related": ["식은 죽 먹기"], "related_v": 2}, {"ko": "식은 죽 먹기", "rom": "Sigeun juk meokgi", "en": "Eating cold porridge — very easy.", "intro_ko": "아주 쉽게 할 수 있는 일이라는 뜻이에요.", "intro": "A task that takes no effort at all.", "nuance": "Same meaning as 누워서 떡 먹기; both are very common.", "level": "Sprout", "examples": [{"ko": "그 정도 숙제는 식은 죽 먹기예요.", "en": "Homework like that is a breeze."}, {"ko": "컴퓨터를 잘하는 동생에게 이건 식은 죽 먹기였어요.", "en": "For my younger brother, who is good with computers, this was easy."}], "related": ["누워서 떡 먹기"], "related_v": 2}, {"ko": "발 없는 말이 천 리 간다", "rom": "Bal eomneun mari cheon ri ganda", "en": "Words without feet travel a thousand miles.", "intro_ko": "말은 순식간에 멀리 퍼지니까 말을 조심해야 한다는 뜻이에요.", "intro": "Rumors spread fast, so be careful what you say.", "nuance": "A warning about gossip; 말 here means \"words\", a pun on 말 (horse).", "level": "Tree", "examples": [{"ko": "그 이야기는 하지 마. 발 없는 말이 천 리 간다잖아.", "en": "Don't say that. Words travel fast, you know."}, {"ko": "비밀이라고 했는데 벌써 다 알아요. 발 없는 말이 천 리 가네요.", "en": "I said it was a secret, but everyone already knows. Word really travels."}], "related": ["낮말은 새가 듣고 밤말은 쥐가 듣는다"], "related_v": 2}, {"ko": "낮말은 새가 듣고 밤말은 쥐가 듣는다", "rom": "Nammareun saega deutgo bammareun jwiga deunneunda", "en": "Birds hear daytime words, and mice hear nighttime words.", "intro_ko": "아무도 안 듣는 것 같아도 누군가 들을 수 있으니 말조심하라는 뜻이에요.", "intro": "Someone is always listening, so watch what you say.", "nuance": "Like \"the walls have ears\".", "level": "Forest", "examples": [{"ko": "여기서 상사 이야기는 하지 마요. 낮말은 새가 듣고 밤말은 쥐가 들어요.", "en": "Don't talk about the boss here. The walls have ears."}, {"ko": "조용히 말해. 낮말은 새가 듣고 밤말은 쥐가 듣는다고 했어.", "en": "Keep your voice down. Someone is always listening."}], "related": ["발 없는 말이 천 리 간다"], "related_v": 2}, {"ko": "원숭이도 나무에서 떨어진다", "rom": "Wonsungido namueseo tteoreojinda", "en": "Even monkeys fall from trees.", "intro_ko": "아무리 잘하는 사람도 실수할 때가 있다는 뜻이에요.", "intro": "Even experts make mistakes.", "nuance": "Used to comfort someone skilled who slipped up.", "level": "Sprout", "examples": [{"ko": "요리사도 가끔 요리를 망쳐요. 원숭이도 나무에서 떨어지잖아요.", "en": "Even chefs ruin a dish sometimes. Even monkeys fall from trees."}, {"ko": "너무 속상해하지 마. 원숭이도 나무에서 떨어질 때가 있어.", "en": "Don't be too upset. Everyone slips up sometimes."}], "related": [], "related_v": 2}, {"ko": "소 잃고 외양간 고친다", "rom": "So ilko oeyanggan gochinda", "en": "Fixing the barn after losing the cow.", "intro_ko": "일이 이미 잘못된 뒤에 대책을 세운다는 뜻이에요.", "intro": "Taking precautions only after the damage is done.", "nuance": "Like \"closing the barn door after the horse has bolted\"; usually critical.", "level": "Tree", "examples": [{"ko": "사고가 난 뒤에야 신호등을 설치했어요. 소 잃고 외양간 고치는 거죠.", "en": "They only put up traffic lights after the accident. Too little, too late."}, {"ko": "파일을 다 잃어버리고 나서 백업을 시작했어요. 소 잃고 외양간 고친 셈이에요.", "en": "I started backing up only after losing all my files."}], "related": [], "related_v": 2}, {"ko": "우물 안 개구리", "rom": "Umul an gaeguri", "en": "A frog in a well.", "intro_ko": "넓은 세상을 모르고 자기가 아는 것이 전부라고 생각하는 사람을 말해요.", "intro": "Someone with a narrow view who thinks their small world is everything.", "nuance": "Often used about yourself, after travel or a new experience opens your eyes.", "level": "Sprout", "examples": [{"ko": "외국에 가 보니 제가 우물 안 개구리였다는 걸 알았어요.", "en": "After going abroad, I realized I had been a frog in a well."}, {"ko": "우물 안 개구리가 되지 않으려면 다양한 사람을 만나야 해요.", "en": "To avoid becoming narrow-minded, you should meet all kinds of people."}], "related": [], "related_v": 2}, {"ko": "그림의 떡", "rom": "Geurimui tteok", "en": "Rice cake in a picture.", "intro_ko": "마음에 들어도 가질 수 없거나 이용할 수 없는 것을 말해요.", "intro": "Something you want but can never have.", "nuance": "Like \"pie in the sky\"; common when talking about prices.", "level": "Sprout", "examples": [{"ko": "저 가방은 너무 비싸서 저한테는 그림의 떡이에요.", "en": "That bag is way too expensive; it is pie in the sky for me."}, {"ko": "다이어트 중이라 케이크는 그림의 떡이야.", "en": "I'm on a diet, so the cake is just something to look at."}], "related": [], "related_v": 2}, {"ko": "고래 싸움에 새우 등 터진다", "rom": "Gorae ssaume saeu deung teojinda", "en": "When whales fight, the shrimp's back breaks.", "intro_ko": "힘센 사람들이 싸울 때 약한 사람이 피해를 본다는 뜻이에요.", "intro": "The weak get hurt when the powerful fight.", "nuance": "Used about big companies, countries, or bosses in conflict.", "level": "Tree", "examples": [{"ko": "두 회사가 싸우는 바람에 작은 가게들이 힘들어졌어요. 고래 싸움에 새우 등 터진 거죠.", "en": "The two companies fought and small shops suffered."}, {"ko": "부모님이 싸우시면 아이들이 힘들어요. 고래 싸움에 새우 등 터지는 거예요.", "en": "When parents fight, the kids suffer."}], "related": [], "related_v": 2}, {"ko": "호랑이도 제 말 하면 온다", "rom": "Horangido je mal hamyeon onda", "en": "Speak of the tiger and it appears.", "intro_ko": "어떤 사람 이야기를 하고 있을 때 마침 그 사람이 나타났을 때 쓰는 말이에요.", "intro": "Said when the person you were just talking about shows up.", "nuance": "Exactly like \"speak of the devil\"; very common in daily talk.", "level": "Sprout", "examples": [{"ko": "어, 민수 왔다! 호랑이도 제 말 하면 온다더니.", "en": "Oh, here's Minsu! Speak of the devil."}, {"ko": "지금 네 이야기 하고 있었어. 호랑이도 제 말 하면 온다니까.", "en": "We were just talking about you. Speak of the devil."}], "related": [], "related_v": 2}, {"ko": "윗물이 맑아야 아랫물이 맑다", "rom": "Winmuri malgaya araenmuri makda", "en": "The water downstream is clear only if the water upstream is clear.", "intro_ko": "윗사람이 바르게 행동해야 아랫사람도 바르게 행동한다는 뜻이에요.", "intro": "Leaders must set a good example.", "nuance": "Used about parents, bosses, and politicians.", "level": "Forest", "examples": [{"ko": "부모가 먼저 책을 읽어야 아이도 읽어요. 윗물이 맑아야 아랫물이 맑죠.", "en": "Parents have to read first for kids to read. Lead by example."}, {"ko": "팀장님이 늘 일찍 오시니까 팀원들도 일찍 와요. 윗물이 맑아야 아랫물이 맑다는 말이 맞아요.", "en": "Our team leader always comes early, so the team does too."}], "related": [], "related_v": 2}, {"ko": "콩 심은 데 콩 나고 팥 심은 데 팥 난다", "rom": "Kong simeun de kong nago pat simeun de pat nanda", "en": "Plant beans and you get beans; plant red beans and you get red beans.", "intro_ko": "어떤 일이든 원인에 따라 결과가 생긴다는 뜻이에요.", "intro": "You reap what you sow.", "nuance": "Used about effort and results, or children resembling parents.", "level": "Tree", "examples": [{"ko": "열심히 공부했으니까 좋은 점수가 나왔지. 콩 심은 데 콩 나는 거야.", "en": "You studied hard, so you got a good score. You reap what you sow."}, {"ko": "노력 없이 결과를 바라면 안 돼요. 콩 심은 데 콩 나고 팥 심은 데 팥 나요.", "en": "You can't expect results without effort."}], "related": [], "related_v": 2}, {"ko": "하늘이 무너져도 솟아날 구멍이 있다", "rom": "Haneuri muneojyeodo sosanal gumeongi itda", "en": "Even if the sky falls, there is a hole to escape through.", "intro_ko": "아무리 어려운 상황에도 해결 방법은 있다는 뜻이에요.", "intro": "There is always a way out, however bad things get.", "nuance": "A comforting proverb for someone in trouble.", "level": "Tree", "examples": [{"ko": "너무 걱정하지 마. 하늘이 무너져도 솟아날 구멍이 있어.", "en": "Don't worry too much. There's always a way out."}, {"ko": "일이 잘 안 풀려도 포기하지 마세요. 하늘이 무너져도 솟아날 구멍이 있어요.", "en": "Even if things aren't working out, don't give up."}], "related": [], "related_v": 2}, {"ko": "말 한마디로 천 냥 빚을 갚는다", "rom": "Mal hanmadiro cheon nyang bijeul gamneunda", "en": "One kind word can repay a debt of a thousand nyang.", "intro_ko": "말을 잘하면 어려운 일도 해결할 수 있다는 뜻이에요.", "intro": "Kind, well-chosen words can solve big problems.", "nuance": "Used when stressing politeness or a sincere apology.", "level": "Tree", "examples": [{"ko": "먼저 미안하다고 말해 봐. 말 한마디로 천 냥 빚을 갚는다잖아.", "en": "Try apologizing first. One kind word can fix a lot."}, {"ko": "친절하게 말했더니 문제가 쉽게 해결됐어요. 말 한마디로 천 냥 빚을 갚는다는 말이 맞네요.", "en": "I spoke kindly and the problem was solved easily."}], "related": ["가는 말이 고와야 오는 말이 곱다"], "related_v": 2}, {"ko": "빈 수레가 요란하다", "rom": "Bin surega yoranhada", "en": "An empty cart is the noisiest.", "intro_ko": "실력이나 아는 것이 없는 사람이 오히려 더 떠든다는 뜻이에요.", "intro": "Those who know the least talk the most.", "nuance": "Like \"empty vessels make the most noise\"; a criticism.", "level": "Tree", "examples": [{"ko": "자기 자랑만 하는 사람은 실력이 없을 때가 많아요. 빈 수레가 요란하죠.", "en": "People who only brag often lack skill."}, {"ko": "그 사람은 말만 많고 하는 일은 없어. 빈 수레가 요란한 거야.", "en": "He talks a lot but does nothing."}], "related": [], "related_v": 2}, {"ko": "바늘 도둑이 소도둑 된다", "rom": "Baneul doduki sododuk doenda", "en": "A needle thief becomes a cow thief.", "intro_ko": "작은 나쁜 일을 계속하면 큰 나쁜 일을 하게 된다는 뜻이에요.", "intro": "Small wrongs grow into big ones.", "nuance": "Often said to children about small lies or stealing.", "level": "Tree", "examples": [{"ko": "작은 거짓말도 하면 안 돼. 바늘 도둑이 소도둑 된다고 했어.", "en": "Even small lies are wrong. Small wrongs grow."}, {"ko": "처음에는 조금씩 늦다가 이제는 매일 늦어요. 바늘 도둑이 소도둑 되는 거죠.", "en": "At first he was a little late; now he is late every day."}], "related": [], "related_v": 2}, {"ko": "개구리 올챙이 적 생각 못 한다", "rom": "Gaeguri olchaengi jeok saenggak mot handa", "en": "The frog forgets it was once a tadpole.", "intro_ko": "처지가 좋아진 사람이 어려웠던 옛날을 잊고 잘난 척한다는 뜻이에요.", "intro": "Someone who has made it forgets their humble beginnings.", "nuance": "A criticism of people who look down on beginners.", "level": "Tree", "examples": [{"ko": "신입 때는 자기도 실수했으면서 이제 후배를 혼내요. 개구리 올챙이 적 생각 못 하네요.", "en": "He made mistakes as a newbie, but now he scolds juniors."}, {"ko": "부자가 되더니 옛날 친구들을 무시해요. 개구리 올챙이 적 생각 못 하는 거죠.", "en": "Since getting rich, he ignores his old friends."}], "related": [], "related_v": 2}, {"ko": "꿩 먹고 알 먹고", "rom": "Kkwong meokgo al meokgo", "en": "Eating the pheasant and its eggs too.", "intro_ko": "한 가지 일로 두 가지 이익을 얻는다는 뜻이에요.", "intro": "Getting two benefits from one action.", "nuance": "Like \"killing two birds with one stone\", but always positive.", "level": "Sprout", "examples": [{"ko": "운동도 하고 돈도 아끼려고 자전거로 출근해요. 꿩 먹고 알 먹고죠.", "en": "I bike to work to exercise and save money. Two birds, one stone."}, {"ko": "한국 드라마를 보면 재미도 있고 공부도 돼요. 꿩 먹고 알 먹고예요.", "en": "Korean dramas are fun and help me study."}], "related": ["일석이조"], "related_v": 2}, {"ko": "일석이조", "rom": "Ilseogijo", "en": "One stone, two birds.", "intro_ko": "한 가지 일을 해서 두 가지 이익을 얻는다는 뜻이에요.", "intro": "Getting two results from one action.", "nuance": "A four-character idiom (사자성어); a bit more formal than 꿩 먹고 알 먹고.", "level": "Tree", "examples": [{"ko": "걸어서 출근하면 운동도 되고 교통비도 아끼니까 일석이조예요.", "en": "Walking to work gives me exercise and saves bus fare."}, {"ko": "한국 친구와 언어 교환을 하면 친구도 생기고 한국어도 늘어요. 일석이조죠.", "en": "Language exchange gets you a friend and better Korean."}], "related": ["꿩 먹고 알 먹고"], "related_v": 2}, {"ko": "작심삼일", "rom": "Jaksimsamil", "en": "A resolution that lasts three days.", "intro_ko": "굳게 결심한 일이 사흘을 못 가서 흐지부지된다는 뜻이에요.", "intro": "A resolution that falls apart within days.", "nuance": "Extremely common around New Year and diets.", "level": "Sprout", "examples": [{"ko": "새해에 운동을 결심했는데 또 작심삼일이 됐어요.", "en": "I resolved to work out at New Year, but it fizzled out again."}, {"ko": "작심삼일이 되지 않게 친구랑 같이 공부하기로 했어요.", "en": "So it doesn't fizzle out, I decided to study with a friend."}], "related": [], "related_v": 2}, {"ko": "눈코 뜰 새 없다", "rom": "Nunko tteul sae eopda", "en": "No time to open your eyes or nose.", "intro_ko": "정신없이 아주 바쁘다는 뜻이에요.", "intro": "Extremely busy.", "nuance": "Very common at work; 새 here means \"time to spare\".", "level": "Sprout", "examples": [{"ko": "연말이라 회사 일이 많아서 눈코 뜰 새 없어요.", "en": "It's the end of the year, so I'm swamped at work."}, {"ko": "이사 준비 때문에 요즘 눈코 뜰 새가 없어.", "en": "I've been crazy busy getting ready to move."}], "related": [], "related_v": 2}, {"ko": "발이 넓다", "rom": "Bari neolda", "en": "To have wide feet.", "intro_ko": "아는 사람이 많다는 뜻이에요.", "intro": "To know a lot of people; to be well connected.", "nuance": "A compliment; 발 (foot) stands for how far your social circle reaches.", "level": "Sprout", "examples": [{"ko": "수진 씨는 발이 넓어서 모르는 사람이 없어요.", "en": "Sujin knows everyone."}, {"ko": "발이 넓은 친구 덕분에 좋은 사람들을 많이 만났어요.", "en": "Thanks to my well-connected friend, I met lots of great people."}], "related": [], "related_v": 2}, {"ko": "손이 크다", "rom": "Soni keuda", "en": "To have big hands.", "intro_ko": "음식이나 물건을 아주 넉넉하게 준비하거나 주는 성격이라는 뜻이에요.", "intro": "Generous; always making or giving too much.", "nuance": "Classic for moms and grandmothers who cook too much food.", "level": "Sprout", "examples": [{"ko": "우리 엄마는 손이 커서 음식을 항상 너무 많이 하세요.", "en": "My mom is so generous; she always makes way too much food."}, {"ko": "할머니가 손이 크셔서 김치를 백 포기나 담그셨어요.", "en": "Grandma made a hundred heads of kimchi; she never makes a little."}], "related": [], "related_v": 2}, {"ko": "입이 짧다", "rom": "Ibi jjalda", "en": "To have a short mouth.", "intro_ko": "음식을 조금만 먹거나 가리는 것이 많다는 뜻이에요.", "intro": "A picky or light eater.", "nuance": "Used about children or people who eat little.", "level": "Tree", "examples": [{"ko": "동생은 입이 짧아서 밥을 반도 안 먹어요.", "en": "My little brother is a picky eater; he doesn't even eat half his rice."}, {"ko": "입이 짧은 아이를 위해 엄마가 여러 반찬을 만드셨어요.", "en": "Mom made several side dishes for her picky child."}], "related": [], "related_v": 2}, {"ko": "귀가 얇다", "rom": "Gwiga yalda", "en": "To have thin ears.", "intro_ko": "남의 말을 쉽게 믿거나 따른다는 뜻이에요.", "intro": "Easily influenced by what others say.", "nuance": "Often said about yourself when you buy something because of an ad or friend.", "level": "Tree", "examples": [{"ko": "저는 귀가 얇아서 광고만 보면 사고 싶어져요.", "en": "I am easily swayed; whenever I see an ad, I want to buy it."}, {"ko": "귀가 얇은 사람은 가짜 뉴스에 속기 쉬워요.", "en": "People who believe everything they hear are easily fooled by fake news."}], "related": [], "related_v": 2}, {"ko": "눈이 높다", "rom": "Nuni nopda", "en": "To have high eyes.", "intro_ko": "보는 기준이 높아서 웬만한 것은 마음에 들어 하지 않는다는 뜻이에요.", "intro": "Having high standards (especially for partners or products).", "nuance": "Very common when talking about dating.", "level": "Sprout", "examples": [{"ko": "제 친구는 눈이 높아서 아직 남자친구가 없어요.", "en": "My friend has high standards, so she doesn't have a boyfriend yet."}, {"ko": "눈이 너무 높으면 마음에 드는 집을 찾기 어려워요.", "en": "If your standards are too high, it's hard to find a place you like."}], "related": [], "related_v": 2}, {"ko": "배가 아프다", "rom": "Baega apeuda", "en": "My stomach hurts (from envy).", "intro_ko": "다른 사람이 잘되는 것을 보고 질투가 난다는 뜻이에요.", "intro": "To feel jealous of someone else's success.", "nuance": "Literally \"stomachache\"; context tells you it means envy. Often in 사촌이 땅을 사면 배가 아프다.", "level": "Tree", "examples": [{"ko": "친구가 복권에 당첨됐다니 축하하지만 솔직히 배가 좀 아파요.", "en": "My friend won the lottery. I'm happy for them, but honestly a little jealous."}, {"ko": "사촌이 땅을 사면 배가 아프다는 말이 있어요.", "en": "There is a saying: when your cousin buys land, your stomach hurts."}], "related": [], "related_v": 2}, {"ko": "미역국을 먹다", "rom": "Miyeokgugeul meokda", "en": "To eat seaweed soup.", "intro_ko": "시험에서 떨어졌다는 뜻이에요.", "intro": "To fail an exam.", "nuance": "Slippery seaweed = slipping down; that is why students avoid it before exams.", "level": "Tree", "examples": [{"ko": "이번 운전면허 시험에서 또 미역국을 먹었어요.", "en": "I failed my driving test again."}, {"ko": "시험 전날에는 미역국을 안 먹는 사람도 있어요.", "en": "Some people avoid seaweed soup the day before an exam."}], "related": [], "related_v": 2}, {"ko": "파김치가 되다", "rom": "Pagimchiga doeda", "en": "To become green-onion kimchi.", "intro_ko": "몹시 지쳐서 힘이 하나도 없다는 뜻이에요.", "intro": "To be completely worn out.", "nuance": "Wilted green onions = an exhausted person.", "level": "Tree", "examples": [{"ko": "하루 종일 이사를 했더니 파김치가 됐어요.", "en": "After moving all day, I was totally wiped out."}, {"ko": "야근을 하고 파김치가 돼서 집에 왔어요.", "en": "I came home exhausted after working late."}], "related": [], "related_v": 2}, {"ko": "바가지를 쓰다", "rom": "Bagajireul sseuda", "en": "To wear a gourd bowl.", "intro_ko": "제값보다 훨씬 비싸게 돈을 냈다는 뜻이에요.", "intro": "To get ripped off.", "nuance": "Very useful for travelers; the seller 바가지를 씌우다 (rips you off).", "level": "Sprout", "examples": [{"ko": "관광지에서 택시를 탔다가 바가지를 썼어요.", "en": "I took a taxi at a tourist spot and got ripped off."}, {"ko": "바가지를 쓰지 않으려면 가격을 먼저 물어보세요.", "en": "Ask the price first so you don't get ripped off."}], "related": [], "related_v": 2}, {"ko": "시치미를 떼다", "rom": "Sichimireul ttaeda", "en": "To remove the falcon tag.", "intro_ko": "알면서도 모르는 척한다는 뜻이에요.", "intro": "To pretend not to know; to play innocent.", "nuance": "From removing the owner tag from a hunting falcon.", "level": "Tree", "examples": [{"ko": "동생이 과자를 다 먹고 시치미를 뗐어요.", "en": "My brother ate all the snacks and played innocent."}, {"ko": "시치미 떼지 마. 네가 한 거 다 알아.", "en": "Don't play dumb. I know you did it."}], "related": [], "related_v": 2}, {"ko": "한 귀로 듣고 한 귀로 흘린다", "rom": "Han gwiro deutgo han gwiro heullinda", "en": "Hearing with one ear and letting it out the other.", "intro_ko": "남의 말을 귀담아듣지 않는다는 뜻이에요.", "intro": "In one ear and out the other.", "nuance": "Common when complaining about someone who never listens.", "level": "Sprout", "examples": [{"ko": "엄마 말을 한 귀로 듣고 한 귀로 흘리면 안 돼.", "en": "Don't let what Mom says go in one ear and out the other."}, {"ko": "잔소리는 한 귀로 듣고 한 귀로 흘려요.", "en": "Nagging goes in one ear and out the other."}], "related": [], "related_v": 2}, {"ko": "금강산도 식후경", "rom": "Geumgangsando sikugyeong", "en": "Even Mount Geumgang is sightseeing after a meal.", "intro_ko": "아무리 좋은 것도 배가 불러야 즐길 수 있다는 뜻이에요.", "intro": "Food comes first; you can't enjoy anything on an empty stomach.", "nuance": "Said when you want to eat before doing something fun.", "level": "Tree", "examples": [{"ko": "구경은 이따 하고 밥부터 먹자. 금강산도 식후경이잖아.", "en": "Let's eat first and look around later. Food comes first."}, {"ko": "여행 첫날 맛집부터 갔어요. 금강산도 식후경이니까요.", "en": "On the first day of the trip we went to a good restaurant first."}], "related": [], "related_v": 2}, {"ko": "비 온 뒤에 땅이 굳어진다", "rom": "Bi on dwie ttangi gudeojinda", "en": "The ground hardens after rain.", "intro_ko": "어려운 일을 겪은 뒤에 더 단단해지고 사이가 좋아진다는 뜻이에요.", "intro": "Hard times make things (or relationships) stronger.", "nuance": "Often said after a fight between friends or couples.", "level": "Tree", "examples": [{"ko": "친구와 크게 싸웠는데 지금은 더 친해졌어요. 비 온 뒤에 땅이 굳어지는 거죠.", "en": "We had a big fight, and now we are closer than ever."}, {"ko": "힘든 일을 함께 겪고 팀이 더 단단해졌어요. 비 온 뒤에 땅이 굳어진다는 말이 맞아요.", "en": "Going through a hard time together made the team stronger."}], "related": [], "related_v": 2}, {"ko": "낫 놓고 기역 자도 모른다", "rom": "Nat noko giyeok jado moreunda", "en": "Not knowing the letter ㄱ even with a sickle in front of you.", "intro_ko": "아주 쉬운 것도 모를 만큼 아무것도 모른다는 뜻이에요.", "intro": "Completely ignorant (a sickle is shaped like ㄱ).", "nuance": "A fun one for Hangul learners.", "level": "Forest", "examples": [{"ko": "컴퓨터에 대해서는 낫 놓고 기역 자도 몰라요.", "en": "I don't know the first thing about computers."}, {"ko": "처음 한국에 왔을 때는 낫 놓고 기역 자도 몰랐어요.", "en": "When I first came to Korea, I couldn't even read ㄱ."}], "related": [], "related_v": 2}, {"ko": "쇠뿔도 단김에 빼라", "rom": "Soeppuldo dangime ppaera", "en": "Pull out the ox horn while it is hot.", "intro_ko": "어떤 일을 하려고 마음먹었으면 망설이지 말고 바로 하라는 뜻이에요.", "intro": "Strike while the iron is hot.", "nuance": "Used to push someone to act now.", "level": "Forest", "examples": [{"ko": "하고 싶으면 오늘 바로 신청해. 쇠뿔도 단김에 빼랬어.", "en": "If you want to do it, sign up today. Strike while the iron is hot."}, {"ko": "계획을 세웠으면 쇠뿔도 단김에 빼라고 바로 시작해요.", "en": "Once you've made a plan, start right away."}], "related": [], "related_v": 2}, {"ko": "개천에서 용 난다", "rom": "Gaecheoneseo yong nanda", "en": "A dragon rises from a small stream.", "intro_ko": "어려운 환경에서 크게 성공한 사람이 나온다는 뜻이에요.", "intro": "Someone from humble beginnings achieves great success.", "nuance": "Used about rags-to-riches stories.", "level": "Tree", "examples": [{"ko": "시골 작은 마을에서 유명한 과학자가 나왔어요. 개천에서 용 났네요.", "en": "A famous scientist came from a tiny village. A real success story."}, {"ko": "요즘은 개천에서 용 나기가 어렵다고 말하는 사람이 많아요.", "en": "Many people say it is hard to rise from nothing these days."}], "related": [], "related_v": 2}, {"ko": "공든 탑이 무너지랴", "rom": "Gongdeun tabi muneojirya", "en": "Would a tower built with care collapse?", "intro_ko": "정성을 다해 한 일은 헛되지 않는다는 뜻이에요.", "intro": "Hard work done with care never goes to waste.", "nuance": "Encouragement before results come out.", "level": "Forest", "examples": [{"ko": "그동안 열심히 준비했으니 걱정하지 마. 공든 탑이 무너지랴.", "en": "You've prepared so hard; don't worry. Your effort won't be wasted."}, {"ko": "매일 연습한 덕분에 대회에서 상을 받았어요. 공든 탑이 무너지지 않았네요.", "en": "Thanks to daily practice, I won a prize."}], "related": [], "related_v": 2}, {"ko": "김칫국부터 마신다", "rom": "Gimchitgukbuteo masinda", "en": "Drinking the kimchi soup first.", "intro_ko": "아직 일이 되지도 않았는데 이미 된 것처럼 기대한다는 뜻이에요.", "intro": "Counting your chickens before they hatch.", "nuance": "Teasing; full form: 떡 줄 사람은 생각도 않는데 김칫국부터 마신다.", "level": "Tree", "examples": [{"ko": "면접도 안 봤는데 첫 월급으로 뭘 살지 고민해요. 김칫국부터 마시는 거죠.", "en": "He hasn't even interviewed and is planning what to buy with his first paycheck."}, {"ko": "아직 연락도 안 왔는데 김칫국부터 마시지 마.", "en": "They haven't even called yet. Don't count your chickens."}], "related": [], "related_v": 2}, {"ko": "불난 집에 부채질한다", "rom": "Bullan jibe buchaejilhanda", "en": "Fanning a house on fire.", "intro_ko": "어려운 상황에 있는 사람을 더 힘들게 하거나 화난 사람을 더 화나게 한다는 뜻이에요.", "intro": "Adding fuel to the fire.", "nuance": "Used when someone makes a bad situation worse.", "level": "Tree", "examples": [{"ko": "화가 난 친구한테 그런 말을 하면 불난 집에 부채질하는 거야.", "en": "Saying that to an angry friend is adding fuel to the fire."}, {"ko": "지각한 사람한테 잔소리까지 하면 불난 집에 부채질이에요.", "en": "Nagging someone who is already late just makes it worse."}], "related": [], "related_v": 2}, {"ko": "간이 크다", "rom": "Gani keuda", "en": "To have a big liver.", "intro_ko": "겁이 없고 대담하다는 뜻이에요.", "intro": "Bold; fearless (sometimes recklessly).", "nuance": "The opposite, 간이 작다, means timid.", "level": "Tree", "examples": [{"ko": "혼자 밤에 산에 가다니 정말 간이 크네요.", "en": "Going up the mountain alone at night? You are really brave."}, {"ko": "저는 간이 작아서 무서운 영화를 못 봐요.", "en": "I'm a scaredy-cat, so I can't watch horror movies."}], "related": [], "related_v": 2}, {"ko": "엎드리면 코 닿을 데", "rom": "Eopdeurimyeon ko daeul de", "en": "A place your nose would touch if you lay face down.", "intro_ko": "아주 가까운 거리라는 뜻이에요.", "intro": "Very close by; a stone's throw away.", "nuance": "Great for giving directions casually.", "level": "Tree", "examples": [{"ko": "우리 집은 회사에서 엎드리면 코 닿을 데예요.", "en": "My place is a stone's throw from the office."}, {"ko": "편의점이 엎드리면 코 닿을 데 있어서 편해요.", "en": "The convenience store is right around the corner, which is handy."}], "related": [], "related_v": 2}]$ph$
